const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const colors = { info: '#2563eb', warning: '#d97706', error: '#dc2626' };
const messages = ($getWorkflowStaticData('global').messages || []);
const cards = messages.map((m) => `
  <article style="border-left:4px solid ${colors[m.severity] || '#64748b'}">
    <h2>${esc(m.title)}</h2><small>${esc(m.receivedAt)}</small>
    <pre>${esc(m.text)}</pre>
    ${(m.links || []).map((l) => `<a class="btn" href="${esc(l.url)}">${esc(l.label)}</a>`).join(' ')}
  </article>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mock Inbox</title><style>
body{font-family:system-ui,sans-serif;max-width:760px;margin:24px auto;padding:0 16px;background:#f8fafc;color:#0f172a}
article{background:#fff;border-radius:8px;padding:12px 16px;margin:12px 0;box-shadow:0 1px 2px #0002}
h2{font-size:16px;margin:0 0 4px} pre{white-space:pre-wrap;font-size:13px;background:#f1f5f9;padding:8px;border-radius:6px}
.btn{display:inline-block;padding:6px 14px;border-radius:6px;background:#0f172a;color:#fff;text-decoration:none;margin-right:6px}
</style></head><body><h1>Mock Inbox</h1><p>${messages.length} message(s), newest first. Refresh to update.</p>${cards || '<p>No messages yet.</p>'}</body></html>`;
return [{ json: { html } }];
